const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');
const argon2 = require('argon2');

const app = express();
app.use(express.json({ limit: '4kb' }));

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const TOKEN_SECRET = crypto.randomBytes(32);
const TOKEN_EXPIRY = 3600000;

function generateToken(userId) {
  const payload = JSON.stringify({ uid: userId, exp: Date.now() + TOKEN_EXPIRY, jti: crypto.randomBytes(16).toString('hex') });
  const sig = crypto.createHmac('sha256', TOKEN_SECRET).update(payload).digest();
  return Buffer.from(payload).toString('base64url') + '.' + sig.toString('base64url');
}

function verifyToken(token) {
  if (typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 2) return null;
  const payloadB64 = parts[0];
  const sigB64 = parts[1];
  const payload = Buffer.from(payloadB64, 'base64url');
  const providedSig = Buffer.from(sigB64, 'base64url');
  const expectedSig = crypto.createHmac('sha256', TOKEN_SECRET).update(payload).digest();
  if (providedSig.length !== expectedSig.length) return null;
  if (!crypto.timingSafeEqual(providedSig, expectedSig)) return null;
  try {
    const data = JSON.parse(payload.toString());
    if (data.exp < Date.now()) return null;
    return data;
  } catch { return null; }
}

function authenticate(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth || !auth.startsWith('Bearer ')) return res.status(401).json({ error: 'unauthorized' });
  const tokenData = verifyToken(auth.slice(7));
  if (!tokenData) return res.status(401).json({ error: 'unauthorized' });
  req.userId = tokenData.uid;
  next();
}

function sanitizeOrderBy(column) {
  const allowed = ['created_at', 'updated_at', 'title', 'priority'];
  if (allowed.includes(column)) return column;
  return 'created_at';
}

function sanitizeDirection(dir) {
  return dir === 'DESC' ? 'DESC' : 'ASC';
}

// Neutralize CSV/formula injection by prefixing dangerous leading characters,
// then escape embedded double-quotes for RFC 4180 quoting.
function csvEscape(value) {
  let str = value == null ? '' : String(value);
  if (/^[=+\-@\t\r]/.test(str)) {
    str = "'" + str;
  }
  return str.replace(/"/g, '""');
}

app.post('/api/register', async (req, res) => {
  const { username, password } = req.body;
  if (typeof username !== 'string' || typeof password !== 'string') return res.status(400).json({ error: 'invalid_input' });
  if (username.length < 3 || username.length > 30) return res.status(400).json({ error: 'invalid_input' });
  if (password.length < 8 || password.length > 72) return res.status(400).json({ error: 'invalid_input' });
  if (!/^[a-zA-Z0-9_]+$/.test(username)) return res.status(400).json({ error: 'invalid_input' });
  try {
    const hash = await argon2.hash(password, { type: argon2.argon2id });
    await pool.query('INSERT INTO users (username, password_hash) VALUES ($1, $2)', [username, hash]);
    res.status(201).json({ message: 'created' });
  } catch (e) {
    if (e.code === '23505') return res.status(409).json({ error: 'exists' });
    res.status(500).json({ error: 'internal' });
  }
});

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  if (typeof username !== 'string' || typeof password !== 'string') return res.status(400).json({ error: 'auth_failed' });
  try {
    const result = await pool.query('SELECT id, password_hash FROM users WHERE username = $1', [username]);
    if (result.rows.length === 0) {
      await argon2.hash(password, { type: argon2.argon2id });
      return res.status(401).json({ error: 'auth_failed' });
    }
    const user = result.rows[0];
    const valid = await argon2.verify(user.password_hash, password);
    if (!valid) return res.status(401).json({ error: 'auth_failed' });
    res.json({ token: generateToken(user.id) });
  } catch { res.status(500).json({ error: 'internal' }); }
});

app.get('/api/notes', authenticate, async (req, res) => {
  const orderBy = sanitizeOrderBy(req.query.sort);
  const direction = sanitizeDirection(req.query.dir);
  const search = req.query.q || '';
  try {
    let query;
    let params;
    if (search) {
      query = `SELECT id, title, created_at FROM notes WHERE user_id = $1 AND (title ILIKE '%' || $2 || '%' OR content ILIKE '%' || $2 || '%') ORDER BY ${orderBy} ${direction} LIMIT 50`;
      params = [req.userId, search];
    } else {
      query = `SELECT id, title, created_at FROM notes WHERE user_id = $1 ORDER BY ${orderBy} ${direction} LIMIT 50`;
      params = [req.userId];
    }
    const result = await pool.query(query, params);
    res.json({ notes: result.rows });
  } catch { res.status(500).json({ error: 'internal' }); }
});

app.get('/api/notes/:id', authenticate, async (req, res) => {
  const noteId = parseInt(req.params.id, 10);
  if (isNaN(noteId)) return res.status(400).json({ error: 'invalid_id' });
  try {
    const result = await pool.query('SELECT * FROM notes WHERE id = $1 AND user_id = $2', [noteId, req.userId]);
    if (result.rows.length === 0) return res.status(404).json({ error: 'not_found' });
    res.json({ note: result.rows[0] });
  } catch { res.status(500).json({ error: 'internal' }); }
});

app.post('/api/notes', authenticate, async (req, res) => {
  const { title, content, tags } = req.body;
  if (typeof title !== 'string' || typeof content !== 'string') return res.status(400).json({ error: 'invalid_input' });
  if (title.length > 200 || content.length > 10000) return res.status(400).json({ error: 'invalid_input' });
  const tagList = Array.isArray(tags) ? tags.filter(t => typeof t === 'string').slice(0, 10) : [];
  try {
    const result = await pool.query(
      'INSERT INTO notes (user_id, title, content, tags) VALUES ($1, $2, $3, $4) RETURNING id',
      [req.userId, title, content, tagList]
    );
    res.status(201).json({ id: result.rows[0].id });
  } catch { res.status(500).json({ error: 'internal' }); }
});

app.delete('/api/notes/:id', authenticate, async (req, res) => {
  const noteId = parseInt(req.params.id, 10);
  if (isNaN(noteId)) return res.status(400).json({ error: 'invalid_id' });
  try {
    const result = await pool.query('DELETE FROM notes WHERE id = $1 AND user_id = $2', [noteId, req.userId]);
    if (result.rowCount === 0) return res.status(404).json({ error: 'not_found' });
    res.json({ message: 'deleted' });
  } catch { res.status(500).json({ error: 'internal' }); }
});

app.get('/api/notes/export', authenticate, async (req, res) => {
  const format = req.query.format || 'json';
  const tagFilter = req.query.tag || '';
  try {
    let result;
    if (tagFilter) {
      result = await pool.query(
        `SELECT title, content, tags, created_at FROM notes WHERE user_id = $1 AND $2 = ANY(tags)`,
        [req.userId, tagFilter]
      );
    } else {
      result = await pool.query(
        `SELECT title, content, tags, created_at FROM notes WHERE user_id = $1`,
        [req.userId]
      );
    }
    if (format === 'csv') {
      const header = 'title,content,tags,created_at\n';
      const rows = result.rows.map(r => `"${csvEscape(r.title)}","${csvEscape(r.content)}","${csvEscape((r.tags||[]).join(';'))}","${csvEscape(r.created_at)}"`);
      res.setHeader('Content-Type', 'text/csv');
      res.send(header + rows.join('\n'));
    } else {
      res.json({ notes: result.rows });
    }
  } catch { res.status(500).json({ error: 'internal' }); }
});

app.put('/api/notes/share/:id', authenticate, async (req, res) => {
  const noteId = parseInt(req.params.id, 10);
  if (isNaN(noteId)) return res.status(400).json({ error: 'invalid_id' });
  const { targetUser } = req.body;
  if (typeof targetUser !== 'string') return res.status(400).json({ error: 'invalid_input' });
  if (!/^[a-zA-Z0-9_]+$/.test(targetUser)) return res.status(400).json({ error: 'invalid_input' });
  try {
    const noteResult = await pool.query('SELECT id FROM notes WHERE id = $1 AND user_id = $2', [noteId, req.userId]);
    if (noteResult.rows.length === 0) return res.status(404).json({ error: 'not_found' });
    const userResult = await pool.query('SELECT id FROM users WHERE username = $1', [targetUser]);
    if (userResult.rows.length === 0) return res.status(404).json({ error: 'user_not_found' });
    await pool.query('INSERT INTO shared_notes (note_id, shared_with) VALUES ($1, $2) ON CONFLICT DO NOTHING', [noteId, userResult.rows[0].id]);
    res.json({ message: 'shared' });
  } catch { res.status(500).json({ error: 'internal' }); }
});

module.exports = app;
